     1→import {
     2→  AuthData,
     3→  AuthDataPasswordDetails,
     4→  ClientBuilder,
     5→  SlidingSyncVersion,
     6→  type Session,
     7→} from "@unomed/react-native-matrix-sdk";
     8→import { deleteJotaiStorageAdapter } from "modules/storage/utils";
     9→import RNFS from "react-native-fs";
    10→import { MatrixStorage } from "../../matrix-client/const";
    11→import { MatrixJotaiStore } from "../../matrix-client/const/matrx-jotai-store";
    12→import { MatrixAtoms } from "../../matrix-client/jotai";
    13→import { MatrixCore } from "../../matrix-client/services/MatrixCore";
    14→import { MatrixNotificationService } from "../../push-notifications/service/MatrixNotificationService";
    15→
    16→type LoginWithUsernameAndPasswordData = {
    17→  username: string;
    18→  password: string;
    19→};
    20→
    21→const dataPath = `${RNFS.DocumentDirectoryPath}/matrix/data`;
    22→const cachePath = `${RNFS.CachesDirectoryPath}/matrix/cache`;
    23→
    24→export class AuthService {
    25→  private static async clearCryptoStore() {
    26→    try {
    27→      const dataExists = await RNFS.exists(dataPath);
    28→      const cacheExists = await RNFS.exists(cachePath);
    29→
    30→      if (dataExists) {
    31→        await RNFS.unlink(dataPath);
    32→        console.log("Cleared crypto data store");
    33→      }
    34→
    35→      if (cacheExists) {
    36→        await RNFS.unlink(cachePath);
    37→        console.log("Cleared crypto cache store");
    38→      }
    39→    } catch (error) {
    40→      console.warn("Failed to clear crypto store:", error);
    41→    }
    42→  }
    43→
    44→  public static initialize = async (serverUrl: string) => {
    45→    MatrixCore.instance = await new ClientBuilder()
    46→      .serverNameOrHomeserverUrl(serverUrl)
    47→      .sessionPaths(dataPath, cachePath)
    48→      .autoEnableBackups(false)
    49→      .build();
    50→  };
    51→
    52→  public static hasStoredCredentials = (): boolean => {
    53→    return MatrixStorage.hasStoredCredentials();
    54→  };
    55→
    56→  public static getServerName = () => MatrixCore.getServerName();
    57→
    58→  public static getUser = () => {
    59→    if (!MatrixCore.instance) return null;
    60→    const userId = MatrixCore.instance.userId();
    61→    return userId ? MatrixCore.instance.getProfile(userId) : null;
    62→  };
    63→
    64→  public static restoreSessionForBackground = async (): Promise<boolean> => {
    65→    try {
    66→      if (MatrixCore.instance && MatrixNotificationService.getNotificationClient())
    67→        return true;
    68→
    69→      const credentials = MatrixStorage.getLoginCredentials();
    70→      if (!credentials) return false;
    71→
    72→      await AuthService.initialize(credentials.baseUrl);
    73→
    74→      const client = MatrixCore.getClient();
    75→
    76→      await client.restoreSession({
    77→        accessToken: credentials.accessToken,
    78→        refreshToken: credentials.refreshToken,
    79→        userId: credentials.userId,
    80→        deviceId: credentials.deviceId,
    81→        homeserverUrl: credentials.baseUrl,
    82→        oidcData: undefined,
    83→        slidingSyncVersion: SlidingSyncVersion.Native,
    84→      });
    85→
    86→      await client.encryption().waitForE2eeInitializationTasks();
    87→
    88→      await MatrixNotificationService.ensureNotificationClient();
    89→
    90→      return true;
    91→    } catch (error) {
    92→      console.error("[Background] Failed to restore session:", error);
    93→      return false;
    94→    }
    95→  };
    96→
    97→  public static restoreSession = async (): Promise<boolean> => {
    98→    try {
    99→      const credentials = MatrixStorage.getLoginCredentials();
   100→      if (!credentials) return false;
   101→
   102→      await AuthService.initialize(credentials.baseUrl);
   103→
   104→      const client = MatrixCore.getClient();
   105→
   106→      await client.restoreSession({
   107→        accessToken: credentials.accessToken,
   108→        refreshToken: credentials.refreshToken,
   109→        userId: credentials.userId,
   110→        deviceId: credentials.deviceId,
   111→        homeserverUrl: credentials.baseUrl,
   112→        oidcData: undefined,
   113→        slidingSyncVersion: SlidingSyncVersion.Native,
   114→      });
   115→
   116→      try {
   117→        MatrixCore.profile = await client.getProfile(credentials.userId);
   118→      } catch (error) {
   119→        console.warn("Session validation failed:", error);
   120→        throw new Error("Session is invalid or expired");
   121→      }
   122→
   123→      MatrixCore.syncService = await client.syncService().finish();
   124→
   125→      if (!MatrixCore.syncService) {
   126→        throw new Error("Failed to initialize sync service");
   127→      }
   128→
   129→      await MatrixCore.syncService.start();
   130→
   131→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, MatrixCore.instance);
   132→      MatrixJotaiStore.set(MatrixAtoms.syncService, MatrixCore.syncService);
   133→      MatrixJotaiStore.set(MatrixAtoms.profile, MatrixCore.profile);
   134→
   135→      return true;
   136→    } catch (error) {
   137→      console.warn("Failed to restore session:", error);
   138→
   139→      MatrixStorage.clearLoginCredentials();
   140→      await AuthService.clearCryptoStore();
   141→
   142→      MatrixCore.instance = null;
   143→      MatrixCore.syncService = null;
   144→
   145→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
   146→      MatrixJotaiStore.set(MatrixAtoms.syncService, null);
   147→
   148→      return false;
   149→    }
   150→  };
   151→
   152→  public static setup = async (params: Session) => {
   153→    await AuthService.clearCryptoStore();
   154→
   155→    if (MatrixCore.syncService) await MatrixCore.syncService.stop();
   156→    MatrixCore.instance = null;
   157→    MatrixCore.syncService = null;
   158→
   159→    MatrixStorage.saveLoginCredentials({
   160→      accessToken: params.accessToken,
   161→      refreshToken: params.refreshToken,
   162→      userId: params.userId,
   163→      deviceId: params.deviceId,
   164→      baseUrl: params.homeserverUrl,
   165→    });
   166→
   167→    await AuthService.initialize(params.homeserverUrl);
   168→
   169→    const client = MatrixCore.getClient();
   170→
   171→    await client.restoreSession({
   172→      accessToken: params.accessToken,
   173→      refreshToken: params.refreshToken,
   174→      userId: params.userId,
   175→      deviceId: params.deviceId,
   176→      homeserverUrl: params.homeserverUrl,
   177→      oidcData: undefined,
   178→      slidingSyncVersion: SlidingSyncVersion.Native,
   179→    });
   180→
   181→    try {
   182→      MatrixCore.profile = await client.getProfile(params.userId);
   183→    } catch (error) {
   184→      console.warn("Session validation failed:", error);
   185→      throw new Error("Session is invalid or expired");
   186→    }
   187→
   188→    MatrixCore.syncService = await client.syncService().finish();
   189→
   190→    if (!MatrixCore.syncService) throw new Error("Failed to initialize sync service");
   191→
   192→    await MatrixCore.syncService.start();
   193→    await client.encryption().waitForE2eeInitializationTasks();
   194→
   195→    try {
   196→      const encryption = client.encryption();
   197→      const backupExists = await encryption.backupExistsOnServer();
   198→      console.log("Backup exists on server:", backupExists);
   199→      console.log("Current verification state:", encryption.verificationState());
   200→      const isLastDevice = await encryption.isLastDevice();
   201→      console.log("Is last device:", isLastDevice);
   202→
   203→      MatrixJotaiStore.set(MatrixAtoms.matrixClient, MatrixCore.instance);
   204→      MatrixJotaiStore.set(MatrixAtoms.syncService, MatrixCore.syncService);
   205→      MatrixJotaiStore.set(MatrixAtoms.profile, MatrixCore.profile);
   206→    } catch (error) {
   207→      console.warn("Failed to check backup/verification status:", error);
   208→    }
   209→  };
   210→
   211→  public static login = async ({
   212→    username,
   213→    password,
   214→  }: LoginWithUsernameAndPasswordData) => {
   215→    const client = MatrixCore.getClient();
   216→    await client.login(username, password, undefined, undefined);
   217→    const session = client.session();
   218→    console.log(client.encryption().verificationState(), "verificationState");
   219→
   220→    MatrixCore.instance = null;
   221→
   222→    return session;
   223→  };
   224→
   225→  public static logout = async () => {
   226→    MatrixStorage.clearLoginCredentials();
   227→    deleteJotaiStorageAdapter();
   228→    await AuthService.clearCryptoStore();
   229→
   230→    if (MatrixCore.syncService) await MatrixCore.syncService.stop();
   231→    if (MatrixCore.instance) await MatrixCore.instance.logout();
   232→
   233→    MatrixCore.instance = null;
   234→    MatrixCore.syncService = null;
   235→    MatrixCore.profile = null;
   236→
   237→    MatrixJotaiStore.set(MatrixAtoms.matrixClient, null);
   238→    MatrixJotaiStore.set(MatrixAtoms.syncService, null);
   239→    MatrixJotaiStore.set(MatrixAtoms.profile, null);
   240→  };
   241→
   242→  public static deactivateAccount = async (password: string) => {
   243→    const client = MatrixCore.getClient();
   244→
   245→    try {
   246→      try {
   247→        await client.deactivateAccount(undefined, true);
   248→      } catch {
   249→        // Expected to fail (UIA first step)
   250→      }
   251→
   252→      const userId = client.userId();
   253→      if (!userId) throw new Error("User ID not found");
   254→
   255→      const authData = new AuthData.Password({
   256→        passwordDetails: AuthDataPasswordDetails.create({
   257→          identifier: userId,
   258→          password,
   259→        }),
   260→      });
   261→
   262→      await client.deactivateAccount(authData, true);
   263→      await AuthService.logout();
   264→    } catch (error) {
   265→      console.error("Failed to deactivate account:", error);
   266→      throw error;
   267→    }
   268→  };
   269→}
