     1→import { BottomSheetModal, BottomSheetView } from "@gorhom/bottom-sheet";
     2→import { animateSequence, Block, Text } from "@prototyp/skeletor";
     3→import { RecoveryState } from "@unomed/react-native-matrix-sdk";
     4→import { AuthService } from "modules/auth/service/AuthService";
     5→import { EncryptionService } from "modules/encryption/service/EncryptionService";
     6→import { NavigationContainerRef } from "modules/navigation/const";
     7→import { useCallback, useEffect, useRef, useState } from "react";
     8→import { Dimensions, Image, StyleSheet } from "react-native";
     9→import Toast from "react-native-toast-message";
    10→import { Button, Loading } from "shared/components";
    11→import { usePreventSwipeBack } from "shared/hooks";
    12→import { Colors, TextSize } from "shared/styles";
    13→
    14→interface Props {
    15→  isBottomSheetOpen: boolean;
    16→  setIsBottomSheetOpen: () => void;
    17→}
    18→
    19→const { width } = Dimensions.get("screen");
    20→
    21→export const SignOutBottomSheet: React.FC<Props> = ({
    22→  isBottomSheetOpen,
    23→  setIsBottomSheetOpen,
    24→}) => {
    25→  const ref = useRef<BottomSheetModal>(null);
    26→  const fadeIn = useRef(
    27→    animateSequence(
    28→      { opacity: [0, 1] },
    29→      {
    30→        duration: 200,
    31→      },
    32→    ),
    33→  ).current;
    34→  const [backupState, setBackupState] = useState<MappedBackupState>("unknown");
    35→  const [recoveryState, setRecoveryState] = useState<RecoveryState>(
    36→    RecoveryState.Unknown,
    37→  );
    38→  const isBackupEnabled =
    39→    backupState === "enabled" ||
    40→    (backupState === "unknown" &&
    41→      (recoveryState === RecoveryState.Enabled ||
    42→        recoveryState === RecoveryState.Incomplete));
    43→  const [showBackupSetUpWarning, setShowBackupSetUpWarning] = useState(false);
    44→  const [isSigningOut, setIsSigningOut] = useState(false);
    45→
    46→  const signOut = async () => {
    47→    try {
    48→      setIsSigningOut(true);
    49→      await AuthService.logout();
    50→      handleCancel();
    51→      NavigationContainerRef.reset({
    52→        index: 0,
    53→        routes: [{ name: "splash" }],
    54→      });
    55→      Toast.show({
    56→        type: "success",
    57→        text1: "Successfully signed out",
    58→      });
    59→    } catch (error) {
    60→      console.error("Failed to logout: ", error);
    61→      Toast.show({
    62→        type: "error",
    63→        text1: "Failed to sign out",
    64→      });
    65→    } finally {
    66→      setIsSigningOut(false);
    67→    }
    68→  };
    69→
    70→  const handleBottomSheetClose = useCallback(() => {
    71→    fadeIn.reverse(() => {
    72→      setIsBottomSheetOpen();
    73→      setShowBackupSetUpWarning(false);
    74→    });
    75→  }, [fadeIn, setIsBottomSheetOpen]);
    76→
    77→  const handleCancel = useCallback(() => {
    78→    ref.current?.close();
    79→    handleBottomSheetClose();
    80→  }, [handleBottomSheetClose]);
    81→
    82→  const handleSettings = useCallback(() => {
    83→    handleCancel();
    84→    NavigationContainerRef.navigate("encryption");
    85→  }, [handleCancel]);
    86→
    87→  const handleSignOut = useCallback(() => {
    88→    if (!isBackupEnabled) {
    89→      setShowBackupSetUpWarning(true);
    90→      return;
    91→    }
    92→
    93→    signOut();
    94→  }, [signOut]);
    95→
    96→  usePreventSwipeBack(isBottomSheetOpen);
    97→
    98→  useEffect(() => {
    99→    if (!isBottomSheetOpen) return;
   100→
   101→    fadeIn.start();
   102→    ref.current?.present();
   103→  }, [isBottomSheetOpen, fadeIn]);
   104→
   105→  useEffect(() => {
   106→    const listener = EncryptionService.subscribeToBackupState((state) => {
   107→      setBackupState(state);
   108→    });
   109→
   110→    return () => {
   111→      listener.cancel();
   112→    };
   113→  }, []);
   114→
   115→  useEffect(() => {
   116→    const listener = EncryptionService.subscribeToRecoveryState((state) => {
   117→      setRecoveryState(state);
   118→    });
   119→
   120→    return () => {
   121→      listener.cancel();
   122→    };
   123→  }, []);
   124→
   125→  if (!isBottomSheetOpen) return null;
   126→
   127→  return (
   128→    <>
   129→      {isSigningOut ? <Loading text="Signing out..." /> : null}
   130→      <Block
   131→        absolute
   132→        width={width}
   133→        height="100%"
   134→        offsets={{ left: 0, top: 0 }}
   135→        animations={fadeIn.animations}
   136→        zIndex={9999}
   137→        background={Colors.black70}
   138→      >
   139→        <BottomSheetModal
   140→          ref={ref}
   141→          handleStyle={styles.handle}
   142→          handleIndicatorStyle={styles.handleIndicator}
   143→          backgroundStyle={styles.background}
   144→          enablePanDownToClose
   145→          enableDynamicSizing
   146→          onDismiss={handleBottomSheetClose}
   147→        >
   148→          <BottomSheetView>
   149→            {showBackupSetUpWarning ? (
   150→              <Block
   151→                paddings={{
   152→                  paddingHorizontal: 20,
   153→                  paddingBottom: 20,
   154→                }}
   155→                gap={40}
   156→                align="center"
   157→              >
   158→                <Image source={require("assets/images/key.png")} />
   159→                <Block gap={8} align="center">
   160→                  <Text size={TextSize.large} color={Colors.white}>
   161→                    Recovery not set up
   162→                  </Text>
   163→                  <Text font="InstrumentSans-Regular" textAlign="center">
   164→                    You are about to sign out of your last session. If you sign
   165→                    out now, you will lose access to your encrypted messages.
   166→                  </Text>
   167→                </Block>
   168→                <Block gap={12} width="100%" paddings={[0, 52]}>
   169→                  <Button.Outline onPress={handleSettings}>
   170→                    Settings
   171→                  </Button.Outline>
   172→                  <Button.Warning onPress={signOut}>
   173→                    Sign out anyway
   174→                  </Button.Warning>
   175→                </Block>
   176→              </Block>
   177→            ) : (
   178→              <Block
   179→                paddings={{
   180→                  paddingHorizontal: 20,
   181→                  paddingBottom: 20,
   182→                }}
   183→                gap={40}
   184→              >
   185→                <Block gap={8} align="center">
   186→                  <Text size={TextSize.large} color={Colors.white}>
   187→                    Sign Out
   188→                  </Text>
   189→                  <Text font="InstrumentSans-Regular">
   190→                    Are you sure you want to sign out?
   191→                  </Text>
   192→                </Block>
   193→                <Block gap={12} width="100%" paddings={[0, 52]}>
   194→                  <Button.Warning onPress={handleSignOut}>
   195→                    Sign Out
   196→                  </Button.Warning>
   197→                  <Button.Ghost onPress={handleCancel}>Cancel</Button.Ghost>
   198→                </Block>
   199→              </Block>
   200→            )}
   201→          </BottomSheetView>
   202→        </BottomSheetModal>
   203→      </Block>
   204→    </>
   205→  );
   206→};
   207→
   208→const styles = StyleSheet.create({
   209→  background: {
   210→    backgroundColor: Colors.blackMinus1,
   211→    borderTopLeftRadius: 24,
   212→    borderTopRightRadius: 24,
   213→  },
   214→  handle: {
   215→    borderWidth: 1,
   216→    borderBottomWidth: 0,
   217→    borderTopLeftRadius: 24,
   218→    borderTopRightRadius: 24,
   219→    paddingHorizontal: 12,
   220→    paddingTop: 12,
   221→    paddingBottom: 24,
   222→  },
   223→  handleIndicator: {
   224→    width: 84,
   225→    height: 4,
   226→    backgroundColor: Colors.white50,
   227→  },
   228→});
