    50→
    51→export const Settings: React.FC<NativeStackScreenProps<Routes, "settings">> = ({
    52→  navigation,
    53→}) => {
    54→  const [isSignOutBottomSheetOpen, setIsSignOutBottomSheetOpen] =
    55→    useState(false);
    56→  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
