    16→export const Splash: React.FC<NativeStackScreenProps<Routes, "splash">> = ({
    17→  navigation,
    18→}) => {
    19→  const screenLockPin = useAtomValue(StorageAtoms.screenLockPin);
    20→  const hasSeenOnboarding = useAtomValue(StorageAtoms.hasSeenOnboarding);
    21→  const hasRunIdentityConfirmation = useAtomValue(
    22→    StorageAtoms.hasRunIdentityConfirmation,
    23→  );
    24→  const hasSeenNotificationsIntro = useAtomValue(
    25→    PushNotificationsAtoms.hasSeenNotificationsIntro,
    26→  );
    27→  const transition = useRef(
    28→    animateParallel(
    29→      { opacity: [0, 1], translateY: [40, 0] },
    30→      { duration: 200 },
    31→    ),
    32→  ).current;
    33→
    34→  useEffect(() => {
    35→    const checkAuthAndNavigate = async () => {
    36→      try {
    37→        // Check if we have stored credentials
    38→        if (AuthService.hasStoredCredentials()) {
    39→          const sessionRestored = await AuthService.restoreSession();
    40→          const isVerified = VerificationService.isDeviceVerified();
    41→
    42→          if (sessionRestored && !isVerified && !hasRunIdentityConfirmation) {
    43→            navigation.replace("confirmIdentity");
    44→            return;
    45→          }
    46→
    47→          if (!hasSeenOnboarding) {
    48→            navigation.replace("onboarding");
    49→            return;
    50→          }
    51→
    52→          if (!hasSeenNotificationsIntro) {
    53→            navigation.replace("notificationsIntro");
    54→            return;
    55→          }
    56→
    57→          //If there is a screen lock pin, navigate to the verify pin screen
    58→          if (screenLockPin && sessionRestored) {
    59→            navigation.replace("verifyPin", { isSettingsScreen: false });
    60→            return;
    61→          }
    62→
    63→          if (sessionRestored) {
    64→            // Check if app was opened from a notification
    65→            const pendingRoomId = NotifeeService.consumePendingRoomId();
    66→            await MatrixCore.refreshRoomList();
    67→            if (pendingRoomId) {
    68→              navigation.reset({
    69→                index: 1,
    70→                routes: [
    71→                  { name: "home" },
    72→                  { name: "room", params: { roomId: pendingRoomId } },
    73→                ],
    74→              });
    75→              return;
    76→            }
    77→
    78→            navigation.replace("home");
    79→            return;
    80→          }
    81→        }
    82→
    83→        await AuthService.initialize(MatrixBaseURL);
    84→        navigation.replace("welcome");
    85→      } catch (error) {
    86→        console.warn("Error during auth check:", error);
    87→        navigation.replace("welcome");
    88→      }
    89→    };
    90→
    91→    transition.start(() => {
    92→      setTimeout(checkAuthAndNavigate, 2000);
    93→    });
    94→  }, [
    95→    navigation,
    96→    hasSeenOnboarding,
    97→    hasRunIdentityConfirmation,
    98→    screenLockPin,
    99→    transition,
   100→  ]);
