    13→export class MatrixNotificationService {
    14→  private static notificationClient: NotificationClientInterface | null = null;
    15→
    16→  public static getNotificationClient = () =>
    17→    MatrixNotificationService.notificationClient;
    18→
    19→  public static ensureNotificationClient =
    20→    async (): Promise<NotificationClientInterface | null> => {
    21→      if (MatrixNotificationService.notificationClient)
    22→        return MatrixNotificationService.notificationClient;
    23→      if (!MatrixCore.instance) return null;
    24→
    25→      try {
    26→        MatrixNotificationService.notificationClient =
    27→          await MatrixCore.instance.notificationClient(
    28→            new NotificationProcessSetup.MultipleProcesses(),
    29→          );
    30→        return MatrixNotificationService.notificationClient;
    31→      } catch (error) {
    32→        console.warn("Failed to create notification client:", error);
    33→        return null;
    34→      }
    35→    };
    36→
    37→  public static initNotificationClientForBackground = async (): Promise<void> => {
    38→    const client = MatrixCore.getClient();
    39→    MatrixNotificationService.notificationClient =
    40→      await client.notificationClient(
    41→        new NotificationProcessSetup.MultipleProcesses(),
    42→      );
    43→  };
    44→
    45→  public static getNotificationContent = async (
    46→    roomId: string,
    47→    eventId: string,
    48→  ): Promise<NotificationItem | null> => {
    49→    try {
    50→      if (!MatrixNotificationService.notificationClient) {
    51→        console.warn("Notification client not initialized");
    52→        return null;
    53→      }
    54→
    55→      const status =
    56→        await MatrixNotificationService.notificationClient.getNotification(
    57→          roomId,
    58→          eventId,
    59→        );
    60→
    61→      if (status.tag !== NotificationStatus_Tags.Event) {
    62→        console.warn("Notification status:", status.tag);
    63→        return null;
    64→      }
    65→
    66→      return status.inner.item;
    67→    } catch (error) {
    68→      console.warn("Failed to get notification content:", error);
    69→      return null;
    70→    }
    71→  };
    72→
    73→  public static getPushers = async () => {
    74→    const client = MatrixCore.getClient();
    75→    const session = client.session();
    76→    if (!session) throw new Error("No active session");
    77→
    78→    try {
    79→      const response = await fetch(
    80→        `${session.homeserverUrl}${MATRIX_ENDPOINTS.PUSHERS_GET}`,
    81→        {
    82→          method: "GET",
    83→          headers: {
    84→            "Content-Type": "application/json",
    85→            Authorization: `Bearer ${session.accessToken}`,
    86→          },
    87→        },
    88→      );
    89→
    90→      if (!response.ok) {
    91→        const errorText = await response.text();
    92→        throw new Error(
    93→          `Failed to get pushers: ${response.status} - ${errorText}`,
    94→        );
    95→      }
    96→
    97→      const data = await response.json();
    98→      return data.pushers || [];
    99→    } catch (error) {
   100→      console.error("Failed to get pushers:", error);
   101→      throw error;
   102→    }
   103→  };
   104→
   105→  public static isPusherRegistered = async (pushToken: string) => {
   106→    try {
   107→      const pushers = await MatrixNotificationService.getPushers();
   108→      const session = MatrixCore.getClient().session();
   109→      if (!session) throw new Error("No active session");
   110→
   111→      return pushers.some(
   112→        (pusher: {
   113→          pushkey: string;
   114→          app_id: string;
   115→          device_display_name: string;
