     1→import {
     2→  type FirebaseMessagingTypes,
     3→  getInitialNotification,
     4→  getMessaging,
     5→  getToken,
     6→  onMessage,
     7→  onNotificationOpenedApp,
     8→} from "@react-native-firebase/messaging";
     9→import { AuthService } from "modules/auth/service/AuthService";
    10→import { CallKitService } from "modules/call/service/CallKitService";
    11→import { MatrixStorage } from "modules/matrix-client/const/matrix-storage";
    12→import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
    13→import { NavigationContainerRef } from "modules/navigation/const";
    14→import { MatrixNotificationService } from "modules/push-notifications/service/MatrixNotificationService";
    15→import { RoomService } from "modules/room/service/RoomService";
    16→import { Platform } from "react-native";
    17→import {
    18→  checkNotifications,
    19→  requestNotifications,
    20→  RESULTS,
    21→} from "react-native-permissions";
    22→import {
    23→  formatLocalPushNotificationMessage,
    24→  getDecryptedEventContent,
    25→  isDecryptedEventCall,
    26→} from "../util/formatLocalMessage";
    27→import { NotifeeService } from "./NotifeeService";
    28→
    29→/** Get the current user ID, works in both foreground and background */
    30→const getCurrentUserId = (): string | null => {
    31→  // Try to get from active instance first (foreground)
    32→  const instanceUserId = MatrixCore.instance?.userId();
    33→  if (instanceUserId) return instanceUserId;
    34→
    35→  // Fall back to stored credentials (works in background)
    36→  const credentials = MatrixStorage.getLoginCredentials();
    37→  return credentials?.userId || null;
    38→};
    39→
    40→/**
    41→ * Ensure MatrixService is initialized for background decryption
    42→ * Uses lightweight initialization that doesn't start sync service
    43→ */
    44→const ensureServiceInitialized = async (): Promise<boolean> => {
    45→  const notificationClient = MatrixNotificationService.getNotificationClient();
    46→  if (notificationClient) return true;
    47→
    48→  // Foreground: create notification client if possible
    49→  if (MatrixCore.instance) {
    50→    const client = await MatrixNotificationService.ensureNotificationClient();
    51→    return !!client;
    52→  }
    53→
    54→  // Try to restore session with lightweight background method
    55→  try {
    56→    const restored = await AuthService.restoreSessionForBackground();
    57→    return restored;
    58→  } catch (error) {
    59→    console.error("[Push] Failed to restore session:", error);
    60→    return false;
    61→  }
    62→};
    63→
    64→const handleReceivedMessage = async (
    65→  message: FirebaseMessagingTypes.RemoteMessage,
    66→) => {
    67→  const data = message.data as unknown as NotificationData;
    68→  if (!data) return;
    69→
    70→  // Skip notifications for own messages (works in both foreground and background)
    71→  const currentUserId = getCurrentUserId();
    72→  if (currentUserId && data.sender === currentUserId) return;
    73→
    74→  const isCallOnIOS =
    75→    Platform.OS === "ios" &&
    76→    (data.type === "m.call.invite" || data.type === "m.call.member");
    77→
    78→  if (isCallOnIOS) {
    79→    // Skip if sync-based detection already triggered CallKit for this room
    80→    if (CallKitService.isRingingForRoom(data.room_id)) return;
    81→
    82→    CallKitService.displayIncomingCall({
    83→      roomId: data.room_id,
    84→      roomName: data.room_name || data.sender_display_name || data.sender,
    85→      senderDisplayName: data.sender_display_name || data.sender,
    86→    });
    87→    return;
    88→  }
    89→
    90→  const notificationId = message.messageId || `msg_${Date.now()}`;
    91→  const formattedMessage = formatLocalPushNotificationMessage(data);
    92→
    93→  if (!formattedMessage) return;
    94→
    95→  // Decrypt encrypted messages, then check if it's a call or a regular message
    96→  if (data.type === "m.room.encrypted" && data.room_id && data.event_id) {
    97→    try {
    98→      // Always ensure service is initialized for encrypted messages
    99→      const initialized = await ensureServiceInitialized();
   100→      if (!initialized) return;
   101→
   102→      // Check if the decrypted event is a call — route to CallKit on iOS
   103→      if (Platform.OS === "ios") {
   104→        const isCall = await isDecryptedEventCall(data.room_id, data.event_id);
   105→
   106→        if (isCall) {
   107→          // Skip if sync-based detection already triggered CallKit for this room
   108→          if (CallKitService.isRingingForRoom(data.room_id)) return;
   109→
   110→          const roomName = RoomService.getRoomInfo(
   111→            data.room_id,
   112→          )?.displayName();
   113→
   114→          CallKitService.displayIncomingCall({
   115→            roomId: data.room_id,
   116→            roomName:
   117→              roomName ||
   118→              data.room_name ||
   119→              data.sender_display_name ||
   120→              data.sender,
   121→            senderDisplayName: data.sender_display_name || data.sender,
   122→          });
   123→          return;
   124→        }
   125→      }
   126→
   127→      const roomName = RoomService.getRoomInfo(data.room_id)?.displayName();
   128→      const decryptedContent = await getDecryptedEventContent(
   129→        data.room_id,
   130→        data.event_id,
   131→      );
   132→
   133→      if (decryptedContent) {
   134→        await NotifeeService.create({
   135→          title:
   136→            roomName ||
   137→            data.room_name ||
   138→            data.sender_display_name ||
   139→            data.sender ||
   140→            "Unknown Sender",
   141→          message: `${data.sender_display_name || data.sender}: ${decryptedContent}`,
   142→          id: notificationId,
   143→          data: { room_id: data.room_id },
   144→        });
   145→      } else {
   146→        await NotifeeService.create({
   147→          title: formattedMessage.title,
   148→          message: formattedMessage.message,
   149→          id: notificationId,
   150→          data: { room_id: formattedMessage.room_id },
   151→        });
   152→      }
   153→    } catch (error) {
   154→      console.error("[Push] Failed to decrypt:", error);
   155→    }
   156→
   157→    return;
   158→  }
   159→
   160→  // For non-encrypted messages, show directly
   161→  await NotifeeService.create({
   162→    title: formattedMessage.title,
   163→    message: formattedMessage.message,
   164→    id: notificationId,
   165→    data: { room_id: formattedMessage.room_id },
   166→  });
   167→};
   168→
   169→const handleNotificationPress = async (
   170→  message: FirebaseMessagingTypes.RemoteMessage | null,
   171→  isInitialNotification: boolean,
   172→) => {
   173→  const data = message?.data as unknown as NotificationData;
   174→  const roomId = data?.room_id;
   175→
   176→  if (!roomId || typeof roomId !== "string") return;
   177→
   178→  // For initial notification (cold start), store the room_id
   179→  // and let the Splash screen handle navigation after session restoration
   180→  if (isInitialNotification) {
   181→    NotifeeService.setPendingRoomId(roomId);
   182→    return;
   183→  }
   184→
   185→  // Refresh the room list before navigating to ensure it's up to date
   186→  await MatrixCore.refreshRoomList();
   187→
   188→  // For background events (app already running), navigate directly to room
   189→  NavigationContainerRef.navigate("room", { roomId });
   190→};
   191→
   192→export const PushNotificationsService = {
   193→  getToken: async () => await getToken(getMessaging()),
   194→  /** Register the device with Matrix homeserver for push notifications
   195→   * This should be called after successful login and after push permissions */
   196→  registerPusher: async () => {
   197→    try {
   198→      const fcmToken = await getToken(getMessaging());
   199→      await MatrixNotificationService.setPusher(fcmToken);
   200→      return true;
   201→    } catch (error) {
   202→      console.error("Failed to register push notifications:", error);
   203→      throw error;
   204→    }
   205→  },
   206→  /** Unregister the device from Matrix homeserver */
   207→  unregisterPusher: async () => {
   208→    try {
   209→      const fcmToken = await getMessaging().getToken();
   210→      await MatrixNotificationService.removePusher(fcmToken);
   211→      return true;
   212→    } catch (error) {
   213→      console.error("Failed to unregister push notifications:", error);
   214→      throw error;
   215→    }
   216→  },
   217→  registerListeners: async () => {
   218→    // Foreground message handler
   219→    onMessage(getMessaging(), async (message) => {
   220→      await handleReceivedMessage(message);
   221→    });
   222→
   223→    // When the application is opened from a quit state (cold start)
   224→    getInitialNotification(getMessaging()).then((remoteMessage) => {
   225→      handleNotificationPress(remoteMessage, true);
   226→    });
   227→
   228→    // When the application is running, but in the background
   229→    onNotificationOpenedApp(getMessaging(), (remoteMessage) => {
   230→      handleNotificationPress(remoteMessage, false);
   231→    });
   232→  },
   233→  /** Handle background messages - called from index.js */
   234→  handleBackgroundMessage: async (
   235→    remoteMessage: FirebaseMessagingTypes.RemoteMessage,
   236→  ) => {
   237→    await handleReceivedMessage(remoteMessage);
   238→  },
   239→  checkPermissions: async () => {
   240→    const result = await checkNotifications();
   241→    return result.status === RESULTS.GRANTED;
   242→  },
   243→  requestPermissions: async () => {
   244→    const result = await requestNotifications(["alert"]);
   245→    return result.status === RESULTS.GRANTED;
   246→  },
   247→  subscribeToTopic: async (topic: string) => {
   248→    await getMessaging().subscribeToTopic(topic);
   249→  },
   250→  unsubscribeFromTopic: async (topic: string) => {
   251→    await getMessaging().unsubscribeFromTopic(topic);
   252→  },
   253→};
